package main

import (
	"context"
	"database/sql"
	"fmt"
	_ "github.com/pocketbase/dbx"
	_ "modernc.org/sqlite"
)

func main() {
	db, err := sql.Open("sqlite", "/home/user/myproject/pb_data/data.db")
	if err != nil {
		fmt.Println("open err:", err)
		return
	}
	defer db.Close()
	ctx := context.Background()
	for _, table := range []string{"wallets", "transfers", "users", "_collections"} {
		fmt.Printf("\n=== %s ===\n", table)
		rows, err := db.QueryContext(ctx, "SELECT * FROM "+table)
		if err != nil {
			fmt.Println("err:", err)
			continue
		}
		cols, _ := rows.Columns()
		fmt.Printf("columns: %v\n", cols)
		for rows.Next() {
			raw := make([]interface{}, len(cols))
			ptrs := make([]interface{}, len(cols))
			for i := range raw {
				ptrs[i] = &raw[i]
			}
			_ = rows.Scan(ptrs...)
			fmt.Println(raw)
		}
		rows.Close()
	}
}
