package main

import (
	"log"

	"github.com/pocketbase/pocketbase"
	"github.com/pocketbase/pocketbase/core"
)

// busyTimeoutMs is the busy_timeout (in milliseconds) applied to every
// newly-opened SQLite connection. While SQLite is waiting on a write lock
// it will block up to this many milliseconds before returning SQLITE_BUSY,
// which dramatically reduces the number of SQLITE_BUSY errors the
// application has to retry through.
const busyTimeoutMs = 5000

func main() {
	// Set a SQLite busy_timeout on every new connection so that writers
	// wait gracefully for a lock before the driver surfaces SQLITE_BUSY.
	//
	// Registering the hook at process start is safe because the driver
	// package keeps it in a process-level slice that is consulted on every
	// sqlite.Open call.
	sqliteDriver, err := getSQLiteDriver()
	if err != nil {
		log.Fatal(err)
	}
	sqliteDriver.RegisterConnectionHook(func(conn sqliteConn) error {
		_, err := conn.Exec("PRAGMA busy_timeout = " + intToString(busyTimeoutMs) + ";", nil)
		return err
	})

	app := pocketbase.New()

	app.OnServe().BindFunc(func(se *core.ServeEvent) error {
		se.Router.POST("/api/wallets/transfer", transferHandler)

		return se.Next()
	})

	if err := app.Start(); err != nil {
		log.Fatal(err)
