package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"sync"
	"sync/atomic"
	"time"
)

type result struct {
	ok       bool
	status   int
	body     string
	fromBal  float64
	toBal    float64
}

func doTransfer(client *http.Client, token, from, to string, amount float64) result {
	body, _ := json.Marshal(map[string]any{
		"fromId": from,
		"toId":   to,
		"amount": amount,
	})
	req, _ := http.NewRequest("POST", "http://localhost:8090/api/wallets/transfer", bytes.NewReader(body))
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Authorization", token)
	resp, err := client.Do(req)
	if err != nil {
		return result{ok: false, body: err.Error()}
	}
	defer resp.Body.Close()
	raw, _ := io.ReadAll(resp.Body)
	r := result{status: resp.StatusCode, body: string(raw)}
	if resp.StatusCode == 200 {
		var out struct {
			FromBalance float64 `json:"fromBalance"`
			ToBalance   float64 `json:"toBalance"`
		}
		if err := json.Unmarshal(raw, &out); err == nil {
			r.fromBal = out.FromBalance
			r.toBal = out.ToBalance
		}
		r.ok = true
	}
	return r
}

func main() {
	// Login first
	loginBody, _ := json.Marshal(map[string]any{
		"identity": "tester@example.com",
		"password": "password1234",
	})
	resp, err := http.Post("http://localhost:8090/api/collections/users/auth-with-password",
		"application/json", bytes.NewReader(loginBody))
	if err != nil {
		fmt.Println("login err:", err)
		return
	}
	defer resp.Body.Close()
	raw, _ := io.ReadAll(resp.Body)
	var lr struct {
		Token string `json:"token"`
	}
	if err := json.Unmarshal(raw, &lr); err != nil {
		fmt.Println("login unmarshal err:", err, string(raw))
		return
	}
	if lr.Token == "" {
		fmt.Println("login: empty token, body:", string(raw))
		return
	}
	fmt.Println("got token:", lr.Token[:30], "...")

	const N = 200
	const wA = "8o2p0a7e8z5zwvv"
	const wB = "44ofcbg2d0ni722"

	var (
		okCount      int64
		failCount    int64
		totalDebited int64 // Sum of all *successful* debit amounts on wA
		totalCredited int64 // Sum of all *successful* credit amounts to wB
	)

	// Fire N concurrent transfers wA -> wB, each amount=1.
	// Half of them wA -> wB, half wB -> wA.
	// Use a barrier to release all requests at the same time.
	var wg sync.WaitGroup
	start := make(chan struct{})
	client := &http.Client{Timeout: 30 * time.Second}

	for i := 0; i < N; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			<-start
			var r result
			if i%2 == 0 {
				r = doTransfer(client, lr.Token, wA, wB, 1)
			} else {
				r = doTransfer(client, lr.Token, wB, wA, 1)
			}
			if r.ok {
				atomic.AddInt64(&okCount, 1)
				atomic.AddInt64(&totalDebited, 1)
				atomic.AddInt64(&totalCredited, 1)
			} else {
				atomic.AddInt64(&failCount, 1)
			}
		}(i)
	}

	t0 := time.Now()
	close(start)
	wg.Wait()
	elapsed := time.Since(t0)
	fmt.Printf("\n--- concurrency test: %d concurrent transfers, %v elapsed ---\n", N, elapsed)
	fmt.Printf("successful: %d, failed: %d\n", okCount, failCount)
	fmt.Printf("total amount moved: %d\n", totalDebited)

	// Read final balances from server
	getReq, _ := http.NewRequest("GET", "http://localhost:8090/api/collections/wallets/records?perPage=10", nil)
	getReq.Header.Set("Authorization", lr.Token)
	gresp, _ := http.DefaultClient.Do(getReq)
	graw, _ := io.ReadAll(gresp.Body)
	gresp.Body.Close()
	fmt.Println("\nfinal wallets state:")
	fmt.Println(string(graw))

	// Read transfers count
	tReq, _ := http.NewRequest("GET", "http://localhost:8090/api/collections/transfers/records?perPage=1&fields=id", nil)
	tReq.Header.Set("Authorization", lr.Token)
	tresp, _ := http.DefaultClient.Do(tReq)
	traw, _ := io.ReadAll(tresp.Body)
	tresp.Body.Close()
	fmt.Println("\ntransfers collection:")
	fmt.Println(string(traw))
}

package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"sync"
	"sync/atomic"
	"time"
)

type result struct {
	ok     bool
	status int
	body   string
}

func doTransfer(client *http.Client, token, from, to string, amount float64) result {
	body, _ := json.Marshal(map[string]any{
		"fromId": from,
		"toId":   to,
		"amount": amount,
	})
	req, _ := http.NewRequest("POST", "http://localhost:8090/api/wallets/transfer", bytes.NewReader(body))
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Authorization", token)
	resp, err := client.Do(req)
	if err != nil {
		return result{ok: false, body: err.Error()}
	}
	defer resp.Body.Close()
	raw, _ := io.ReadAll(resp.Body)
	r := result{status: resp.StatusCode, body: string(raw)}
	r.ok = resp.StatusCode == 200
	return r
}

func main() {
	loginBody, _ := json.Marshal(map[string]any{
		"identity": "tester@example.com",
		"password": "password1234",
	})
	resp, _ := http.Post("http://localhost:8090/api/collections/users/auth-with-password",
		"application/json", bytes.NewReader(loginBody))
	raw, _ := io.ReadAll(resp.Body)
	resp.Body.Close()
	var lr struct {
		Token string `json:"token"`
	}
	json.Unmarshal(raw, &lr)

	const N = 500
	const wA = "8o2p0a7e8z5zwvv"
	const wB = "44ofcbg2d0ni722"

	// Top up wallet A with a large balance for this test by first crediting it via transfer
	// (just to make sure we never run out of funds). The current balance is 60.
	// We'll do 1 unit transfers alternating in random directions.
	var (
		okCount      int64
		failCount    int64
		totalMoved   int64
		busyRetries  int64 // not visible externally but kept for completeness
	)

	var wg sync.WaitGroup
	start := make(chan struct{})
	client := &http.Client{Timeout: 60 * time.Second}

	// Mix directions: even go A->B, odd go B->A. Each does amount=0.5.
	// The transfer endpoint requires amount > 0 and we'll round balance
	// values. Use 0.5 transfers and start with 60 in A and 40 in B (total 100).
	for i := 0; i < N; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			<-start
			var r result
			if i%2 == 0 {
				r = doTransfer(client, lr.Token, wA, wB, 0.5)
			} else {
				r = doTransfer(client, lr.Token, wB, wA, 0.5)
			}
			if r.ok {
				atomic.AddInt64(&okCount, 1)
				atomic.AddInt64(&totalMoved, 1)
			} else {
				atomic.AddInt64(&failCount, 1)
				if r.body != "" {
					fmt.Printf("failure [i=%d status=%d]: %s\n", i, r.status, r.body)
				}
			}
		}(i)
	}

	t0 := time.Now()
	close(start)
	wg.Wait()
	elapsed := time.Since(t0)
	fmt.Printf("\n--- %d concurrent transfers (0.5 each), %v elapsed ---\n", N, elapsed)
	fmt.Printf("successful: %d, failed: %d, busyRetries: %d\n", okCount, failCount, busyRetries)
	fmt.Printf("transfers count: %d (should equal okCount + prior count)\n", totalMoved)
}

